from values import V
import docxwriter
m = lambda k, kind, met, key='T': V[key]['M'].loc[(kind, k)][f'{met}_mean']
HL = lambda s: '{{HL:' + s + '}}'
b = [('p', HL('[Date]'), False), ('p', 'Editorial Office, *Remote Sensing* (MDPI)', False), ('p', '', False),
     ('p', 'Dear Editor,', False),
     ('p', 'Please consider our manuscript, "Spatially Validated Landslide Susceptibility Mapping in the Nepal Middle Hills: Sampling Bias, Spectral-Index Leakage and Training–Raster Consistency in Kavrepalanchowk District", for publication as an Article in *Remote Sensing*.', False),
     ('p', f"Machine-learning susceptibility maps built from remote-sensing and terrain rasters are usually validated on random splits of point samples and then applied to every pixel of a region. We show, for a district in central Nepal affected by the landslides of the 26–30 September 2024 rainstorm, what happens when that workflow is held to a stricter standard. Using nested spatial cross-validation with block sizes chosen from a correlogram, we find that a coordinates-only model scores an AUC of {V['g']('Random 5-fold','Coordinates only','RF (default)')[0]:.2f} under random cross-validation, that spectral indices from post-event imagery behave as target leakage, and that several predictors in the training table were not computed the same way as the rasters used for mapping. With leakage removed and all modelling decisions nested, an equal-weight ensemble of calibrated classifiers reaches an out-of-fold AUC of {m('Ensemble-equal','cal','AUC'):.3f}, the highest of all methods in every repeat, and the resulting district map places {__import__('pandas').read_csv('out_class_validation.csv').share_pct.iloc[4]:.0f}% of held-out landslides in its top quintile.", False),
     ('p', 'We think the paper fits *Remote Sensing* because its main lessons concern how satellite-derived and DEM-derived layers enter susceptibility models: the timing of spectral imagery relative to the inventory, the consistency of training samples with the deployed raster stack, and the area of applicability of the resulting map. The workflow, scripts and fold assignments are provided so that the checks can be reused.', False),
     ('p', 'The manuscript is original, has not been published previously and is not under consideration for publication elsewhere. All authors have approved the submitted version and agree with its submission to *Remote Sensing*. The authors declare no conflicts of interest. ' + HL('Add funding statement and any suggested/excluded reviewers if desired.'), False),
     ('p', 'Sincerely,', False), ('p', HL('[Corresponding author name, affiliation, email]'), False)]
docxwriter.write(b, 'Cover_Letter.docx')
